// frontend/src/App.js
import React, { useState, useEffect } from "react";
import ChatInput from "./components/ChatInput";
import MessageList from "./components/MessageList";
import ChartView from "./components/ChartView";
import TableView from "./components/TableView";
import { queryArea, listAreas, uploadExcelFile } from "./api";

function extractLocationFromPrompt(prompt) {
  // Remove common verbs and keep likely location tokens
  const cleaned = prompt
    .toLowerCase()
    .replace(/\b(analyze|analysis|show|give me|compare|trend|market|price|demand|for|the)\b/g, "")
    .replace(/[^\w\s\-]/g, " ")
    .trim();
  return cleaned.split(/\s+/).filter(Boolean).join(" ");
}

export default function App() {
  const [messages, setMessages] = useState([
    { id: 0, role: "system", text: "Ask me about an area (e.g. 'Analyze Wakad')" },
  ]);
  const [loading, setLoading] = useState(false);
  const [chartData, setChartData] = useState(null);
  const [tableData, setTableData] = useState([]);
  const [areas, setAreas] = useState([]);
  const [fileHint, setFileHint] = useState("");

  useEffect(() => {
    // Try to load areas list to hint the user
    listAreas().then(a => {
      setAreas(a || []);
      if (!a || a.length === 0) setFileHint("No dataset loaded — please upload an Excel file.");
    }).catch(() => {
      setFileHint("Could not fetch areas. Backend might not be running or dataset missing.");
    });
  }, []);

  const sendUserMessage = async (text) => {
    const id = Date.now();
    setMessages(prev => [...prev, { id, role: "user", text }]);
    const location = extractLocationFromPrompt(text);
    if (!location) {
      setMessages(prev => [...prev, { id: id+1, role: "assistant", text: `I couldn't extract a location from "${text}". Try: "Analyze Wakad"` }]);
      return;
    }

    setLoading(true);
    try {
      const resp = await queryArea(location);
      // summary, chart, table expected
      const summary = resp.summary || "No summary returned.";
      setMessages(prev => [...prev, { id: id+1, role: "assistant", text: summary }]);
      setChartData(resp.chart || null);
      setTableData(resp.table || []);
      setFileHint("");
    } catch (err) {
      console.error(err);
      const msg = typeof err === "string" ? err : err.message || String(err);
      setMessages(prev => [...prev, { id: id+1, role: "assistant", text: `Error: ${msg}` }]);
    } finally {
      setLoading(false);
    }
  };

  const handleUpload = async (file) => {
    setLoading(true);
    try {
      const res = await uploadExcelFile(file);
      setMessages(prev => [...prev, { id: Date.now(), role: "assistant", text: `Uploaded: ${res.rows || 0} rows loaded.` }]);
      // refresh areas
      const a = await listAreas();
      setAreas(a || []);
      setFileHint("");
    } catch (e) {
      setMessages(prev => [...prev, { id: Date.now(), role: "assistant", text: `Upload failed: ${e.message}` }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container py-3">
      <h3 className="mb-3">RealEstate Chatbot</h3>
      <div className="row">
        <div className="col-md-5">
          <div className="card mb-3">
            <div className="card-body" style={{height: "60vh", overflow: "auto"}}>
              <MessageList messages={messages} />
            </div>
            <div className="card-footer">
              <ChatInput
                onSend={sendUserMessage}
                onUpload={handleUpload}
                loading={loading}
                areasHint={areas}
                fileHint={fileHint}
              />
            </div>
          </div>
        </div>

        <div className="col-md-7">
          <div className="mb-3">
            <h5>Charts</h5>
            <ChartView chart={chartData} />
          </div>

          <div className="mb-3">
            <h5>Data Table (matching rows)</h5>
            <TableView rows={tableData} />
          </div>
        </div>
      </div>
    </div>
  );
}
